// ============================================================
// ConfigUndefaults resets fields that match their default values back to zero.
// Use before persisting to store only explicit user overrides.
func ConfigUndefaults(v *Config) {
	if v == nil {
		return
	}
	if v.SpiffePrefix == DefaultSpiffePrefix {
		v.SpiffePrefix = ""
	}
	if v.TokenAudience == DefaultTokenAudience {
		v.TokenAudience = ""
	}
	if v.KernelCertLifetimeSeconds == DefaultKernelCertLifetimeSeconds {
		v.KernelCertLifetimeSeconds = 0
	}
	if v.HealthProbePort == int32(DefaultHealthProbePort) {
		v.HealthProbePort = 0
	}
	if v.Listener != nil && v.Listener.Host == "0.0.0.0" && v.Listener.Port == 8443 {
		v.Listener = nil
	}
}

